import { Component, Suspense, useMemo } from 'react';
import { useTexture } from '@react-three/drei';
import { useThree } from '@react-three/fiber';
import { bucketURL } from '../../../Settings';
import { FACTION } from '../../config/gameConfig.js';
import GltfModel, { useModelPreload } from './GltfModel.jsx';
import manifest from './modelManifest.json';
import { HULL_TEXTURE_FILES, ROCK_TEXTURE_FILES, configureSurfaceTextures, createShipMaterials } from './shipMaterials.js';

/**
 * Maps a ship class's `model` id to what is drawn.
 *
 * Most ships are GLB files generated by tools/game-models/build_models.py (listed, with
 * their size and engine positions, in modelManifest.json). To use a different model for a
 * ship - for example one downloaded from Sketchfab - drop the GLB into public/assets/game/
 * and add an entry to MODEL_OVERRIDES below.
 */

/**
 * Hand-placed models that do not come from the generator.
 *   file     - path under the asset bucket
 *   scale    - multiplies the file's units into metres
 *   rotation - euler angles that turn the model's nose to -Z
 *   engines  - [x, y, z, radius] exhaust positions in metres, for the engine glow
 */
const MODEL_OVERRIDES = Object.freeze({
    // Captain Tim's ship is the upgraded ship from the site's Project Dawn scene:
    // about 1.09 units long with its bow towards +Z.
    dawnbreaker: {
        file: 'ship-upgrade-transformed.glb',
        scale: 1287,
        rotation: [0, Math.PI, 0],
        size: [510, 190, 1400],
        // No exhaust plumes: the model has its own engine glow.
        engines: [],
    },
});

const FALLBACK_COLORS = Object.freeze({
    [FACTION.DAWN]: '#b9c4d0',
    [FACTION.UMBRA]: '#4a3f55',
    [FACTION.NEUTRAL]: '#8c8f96',
});

/**
 * Ships that borrow another ship's model. The extra player ships fly the Kestrel's hull
 * until their own models are added: give one an entry in MODEL_OVERRIDES and delete its
 * line here.
 */
const MODEL_ALIASES = Object.freeze({ swift: 'kestrel', shrike: 'kestrel', bulwark: 'kestrel' });

/** @returns {{ file: string, size: number[], engines: number[][], scale?: number, rotation?: number[] } | null} */
export function getModelInfo(modelId) {
    const id = MODEL_ALIASES[modelId] ?? modelId;
    return MODEL_OVERRIDES[id] ?? manifest[id] ?? null;
}

/** Every model file the game can show, for preloading behind the loading screen. */
export const ALL_MODEL_FILES = Object.freeze(
    [...Object.values(manifest), ...Object.values(MODEL_OVERRIDES)].map((info) => info.file),
);

/** A plain block the size of the ship, shown if its model file cannot be loaded. */
function PlaceholderHull({ size, faction }) {
    return (
        <mesh>
            <boxGeometry args={size} />
            <meshStandardMaterial color={FALLBACK_COLORS[faction] ?? FALLBACK_COLORS[FACTION.NEUTRAL]} metalness={0.4} roughness={0.5} flatShading />
        </mesh>
    );
}

/** Keeps the game playable when a model is missing (e.g. not uploaded to the bucket yet). */
export class ModelErrorBoundary extends Component {
    constructor(props) {
        super(props);
        this.state = { failed: false };
    }

    static getDerivedStateFromError() {
        return { failed: true };
    }

    render() {
        return this.state.failed ? this.props.fallback : this.props.children;
    }
}

const HULL_TEXTURE_URLS = Object.fromEntries(Object.entries(HULL_TEXTURE_FILES).map(([name, file]) => [name, bucketURL + file]));
const ROCK_TEXTURE_URLS = Object.fromEntries(Object.entries(ROCK_TEXTURE_FILES).map(([name, file]) => [name, bucketURL + file]));
/** One material set per set of loaded textures (in practice: one for the whole game). */
const materialSets = new WeakMap();

/** The ships' plating textures, set up for tiling (suspends until they are loaded). */
export function useHullTextures() {
    const textures = useTexture(HULL_TEXTURE_URLS);
    const anisotropy = useThree((state) => Math.min(8, state.gl.capabilities.getMaxAnisotropy()));
    return useMemo(() => configureSurfaceTextures(textures, anisotropy), [textures, anisotropy]);
}

/** The shared ship materials. */
export function useShipMaterials() {
    const textures = useHullTextures();
    return useMemo(() => {
        if (!materialSets.has(textures)) materialSets.set(textures, createShipMaterials(textures));
        return materialSets.get(textures);
    }, [textures]);
}

/** The asteroid surface textures, set up for tiling. */
export function useRockTextures() {
    const textures = useTexture(ROCK_TEXTURE_URLS);
    const anisotropy = useThree((state) => Math.min(8, state.gl.capabilities.getMaxAnisotropy()));
    return useMemo(() => configureSurfaceTextures(textures, anisotropy), [textures, anisotropy]);
}

function TexturedShip({ info }) {
    const materials = useShipMaterials();
    return <GltfModel url={info.file} scale={info.scale ?? 1} rotation={info.rotation ?? [0, 0, 0]} materials={materials} />;
}

/** The visual model of a ship, nose towards -Z, sized in metres. */
export default function ShipModel({ modelId, faction }) {
    const info = getModelInfo(modelId);
    if (!info) return null;
    const placeholder = <PlaceholderHull size={info.size} faction={faction} />;
    return (
        <ModelErrorBoundary fallback={placeholder}>
            <Suspense fallback={null}>
                <TexturedShip info={info} />
            </Suspense>
        </ModelErrorBoundary>
    );
}

function PreloadOne({ file }) {
    useModelPreload(file);
    return null;
}

useTexture.preload(Object.values(HULL_TEXTURE_URLS));
useTexture.preload(Object.values(ROCK_TEXTURE_URLS));

/**
 * Downloads every ship model while the loading screen is still up, so nothing pops in
 * mid-battle. A missing file only affects that one ship (see ModelErrorBoundary).
 */
export function ShipModelPreloader() {
    return ALL_MODEL_FILES.map((file) => (
        <ModelErrorBoundary key={file} fallback={null}>
            <PreloadOne file={file} />
        </ModelErrorBoundary>
    ));
}
